-- Console mysql, ouverte en root sur le serveur Ubuntu — creation du compte applicatif
CREATE USER 'app_boutique'@'localhost' IDENTIFIED BY '<mot de passe long, unique, jamais reemploye>';
GRANT ALL PRIVILEGES ON *.* TO 'app_boutique'@'localhost';
FLUSH PRIVILEGES;
SHOW GRANTS FOR 'app_boutique'@'localhost';

